#!/usr/bin/env perl
use strict;
use warnings;
use utf8;
use FindBin;
use lib $FindBin::Bin;
use ReleaseUtil qw(verify_release read_changelog json_file curl_response file_digest ensure_build);
use Cwd qw(abs_path);
use File::Spec;
use JSON::PP;
use Getopt::Long qw(GetOptions);

# ==============================================================================
# deploy-github.pl
# 
# Creates a GitHub Release for SlackHacks using the GitHub REST API and uploads
# the packaged zip artifact generated by build.sh.
#
# Prerequisites:
# 1. Proton Pass CLI (pass-cli) installed and authenticated.
# 2. GitHub Personal Access Token (classic or fine-grained with contents:write)
#    stored in Proton Pass.
# ==============================================================================

my $script_dir = $FindBin::Bin;
my $repo_root  = abs_path(File::Spec->catdir($script_dir, ".."));
chdir($repo_root) or die "Cannot change directory to $repo_root: $!\n";

# Helper to load .env file if present
sub load_dotenv {
    my ($file) = @_;
    return unless -f $file;
    open my $fh, "<:encoding(UTF-8)", $file
        or die "Error: Cannot read configuration file $file: $!\n";
    while (my $line = <$fh>) {
        $line =~ s/^\s+|\s+$//g;
        next if $line eq "" || $line =~ /^#/;
        if ($line =~ /^(?:export\s+)?([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.*)$/) {
            my ($key, $val) = ($1, $2);
            $val =~ s/^['"]|['"]$//g;
            $ENV{$key} = $val unless defined $ENV{$key};
        }
    }
    close $fh;
}

my $defaults_file = File::Spec->catfile($script_dir, "defaults.env");
die "Error: Required configuration file scripts/defaults.env is missing.\n" unless -f $defaults_file;
load_dotenv(File::Spec->catfile($repo_root, ".env"));
load_dotenv($defaults_file);

# ------------------------------------------------------------------------------
# Configurable Variables & Settings (Environment variables take precedence)
# ------------------------------------------------------------------------------
sub require_config {
    my ($name) = @_;
    die "Error: Required setting $name is missing. Check scripts/defaults.env.\n"
        unless defined $ENV{$name} && length $ENV{$name};
    return $ENV{$name};
}

my $addon_name             = require_config("ADDON_NAME");
my $toc_file               = require_config("TOC_FILE");
my $dist_dir               = require_config("DIST_DIR");
my $zip_name               = require_config("ZIP_NAME");
my $tag_prefix             = require_config("TAG_PREFIX");
my $changelog_dir          = require_config("CHANGELOG_DIR");
my $release_title_prefix   = require_config("RELEASE_TITLE_PREFIX");
my $github_api_version     = require_config("GITHUB_API_VERSION");

my $github_repo            = require_config("GITHUB_REPO");
my $target_commitish       = require_config("TARGET_COMMITISH");

my $is_draft               = (require_config("IS_DRAFT") =~ /^(1|true|yes)$/i) ? JSON::PP::true : JSON::PP::false;
my $is_prerelease          = (require_config("IS_PRERELEASE") =~ /^(1|true|yes)$/i) ? JSON::PP::true : JSON::PP::false;
my $changelog_file         = defined $ENV{CHANGELOG_FILE} ? $ENV{CHANGELOG_FILE}
    : die "Error: Required setting CHANGELOG_FILE is missing. Check scripts/defaults.env.\n";

# Proton Pass CLI settings
my $proton_pass_item       = require_config("PROTON_PASS_ITEM_GITHUB");
my $proton_pass_vault      = require_config("PROTON_PASS_VAULT");
my $proton_pass_attribute  = require_config("PROTON_PASS_ATTRIBUTE");
my $proton_pass_cli_bin    = require_config("PROTON_PASS_CLI_BIN");

my $dry_run = 0;
my $rerelease = 0;
GetOptions('dry-run|n' => \$dry_run, 'rerelease' => \$rerelease)
    or die "Usage: $0 [--dry-run] [--rerelease]\n";
die "Error: Unexpected arguments: @ARGV\n" if @ARGV;

# ------------------------------------------------------------------------------
# Helpers: Browser Launch & Proton Pass Login
# ------------------------------------------------------------------------------
sub open_url_in_browser {
    my ($url) = @_;
    if ($^O eq 'MSWin32' || $^O eq 'msys' || $^O eq 'cygwin') {
        if (-x '/usr/bin/start') {
            system('/usr/bin/start', $url);
        } elsif (-x '/c/Windows/explorer.exe') {
            system('/c/Windows/explorer.exe', $url);
        } else {
            system('start', $url);
        }
    } elsif ($^O eq 'darwin') {
        system('open', $url);
    } else {
        system('xdg-open', $url);
    }
}

sub run_pass_cli_login {
    my ($bin) = @_;
    print "\nStarting Proton Pass login...\n";

    open my $pipe, "-|", $bin, "login" or do {
        warn "Failed to execute '$bin login': $!\n";
        return 0;
    };

    my $browser_opened = 0;
    while (my $line = <$pipe>) {
        print $line;
        if (!$browser_opened && $line =~ m{(https://account\.proton\.me\S+)}) {
            my $url = $1;
            print "\n[Opening your browser automatically to complete authentication...]\n";
            open_url_in_browser($url);
            $browser_opened = 1;
        }
    }
    close $pipe;
    return ($? == 0);
}

sub clean_stale_proton_pass_session {
    my $appdata = $ENV{APPDATA} || '';
    if ($appdata ne '') {
        my $stale_file = File::Spec->catfile($appdata, "proton-pass-cli", ".session", "session.json");
        if (-f $stale_file) {
            unlink $stale_file;
        }
    }
}

# ------------------------------------------------------------------------------
# Helper: Fetch secret from Proton Pass CLI
# ------------------------------------------------------------------------------
sub fetch_secret_from_proton_pass {
    my ($item, $vault, $attr) = @_;

    if ($ENV{GITHUB_TOKEN} && $ENV{GITHUB_TOKEN} =~ /\S/) {
        return $ENV{GITHUB_TOKEN};
    }

    my @cmd = ($proton_pass_cli_bin, "item", "view", "--item-title", $item, "--field", $attr);
    push @cmd, "--vault-name", $vault if $vault ne "";

    my $run_query = sub {
        my $cmd_str = join(" ", map { /\s/ ? qq{"$_"} : $_ } @cmd);
        my $output = `$cmd_str 2>&1`;
        my $status = $? >> 8;
        return ($status, $output);
    };

    my ($status, $output) = $run_query->();

    # Check for stale corrupted session in Windows file lock state
    if ($status != 0 && $output =~ /Session is some but is not logged in|Error deleting base dir/i) {
        print "Detected stale Proton Pass session file. Cleaning up...\n";
        clean_stale_proton_pass_session();
        ($status, $output) = $run_query->();
    }

    # If unauthenticated, locked, or no session, trigger browser login
    if ($status != 0 && $output =~ /no session|requires an authenticated client|lock|not logged in/i) {
        print "Proton Pass session is unauthenticated or expired.\n";
        run_pass_cli_login($proton_pass_cli_bin);
        ($status, $output) = $run_query->();
    }

    if ($status == 0 && defined $output) {
        $output =~ s/^\s+|\s+$//g;
        if ($output =~ /^\Q$attr\E:\s*(.+)$/i) {
            $output = $1;
            $output =~ s/^\s+|\s+$//g;
        }
        return $output if $output ne "";
    }

    warn "Error: Could not retrieve secret for item '$item' from Proton Pass.\n";
    warn "Output: $output\n" if defined $output && $output =~ /\S/;
    return undef;
}

# ------------------------------------------------------------------------------
# Step 1: Extract Version from SlackHacks.toc & Check Build Artifact
# ------------------------------------------------------------------------------
die "Error: $toc_file not found in $repo_root\n" unless -f $toc_file;

open my $fh, "<:encoding(UTF-8)", $toc_file or die "Cannot open $toc_file: $!\n";
my $version;
while (my $line = <$fh>) {
    if ($line =~ /^\s*##\s*Version:\s*(.+)$/i) {
        $version = $1;
        $version =~ s/^\s+|\s+$//g;
        $version =~ s/^v//i; # strip leading v if present
        last;
    }
}
close $fh;

die "Error: Could not extract version from $toc_file\n" unless defined $version && length($version);

my $tag_name      = "$tag_prefix$version";
my $release_title = "$release_title_prefix$version";
my $zip_path      = File::Spec->catfile($dist_dir, $zip_name);

my $commit = verify_release($tag_name, $target_commitish);

ensure_build($script_dir, $zip_path, $commit) unless $dry_run;

die "Error: Build output '$zip_path' not found.\n" unless $dry_run || -f $zip_path;

# ------------------------------------------------------------------------------
# Step 2: Retrieve GitHub Token from Proton Pass
# ------------------------------------------------------------------------------
my $github_token;
if ($dry_run) {
    print "[Dry Run] Skipping Proton Pass token retrieval.\n";
    $github_token = "DRY_RUN_TOKEN";
} else {
    print "Fetching GitHub Token from Proton Pass...\n";
    $github_token = fetch_secret_from_proton_pass($proton_pass_item, $proton_pass_vault, $proton_pass_attribute);
    die "Error: Failed to retrieve GitHub API token. Set GITHUB_TOKEN or check PROTON_PASS_ITEM_GITHUB in scripts/defaults.env and your Proton Pass item.\n"
        unless defined $github_token;
    print "Successfully retrieved GitHub Token.\n";
}

# ------------------------------------------------------------------------------
# Step 3: Prepare Release Notes / Body
# ------------------------------------------------------------------------------
my $release_body;
($changelog_file, $release_body) = read_changelog($changelog_file, $changelog_dir, $tag_name);
# GitHub's generator appends commit-based notes; the changelog is the authoritative body.
my $generate_release_notes = JSON::PP::false;

# ------------------------------------------------------------------------------
# Step 4: Create GitHub Release
# ------------------------------------------------------------------------------
my $json_codec = JSON::PP->new->utf8->canonical;

my $payload = {
    tag_name               => $tag_name,
    target_commitish       => $target_commitish,
    name                   => $release_title,
    body                   => $release_body,
    draft                  => $is_draft,
    prerelease             => $is_prerelease,
    generate_release_notes => $generate_release_notes,
};

my $api_url = "https://api.github.com/repos/$github_repo/releases";

print "=== GitHub Release Summary ===\n";
print "Repository:          $github_repo\n";
print "Tag Name:            $tag_name\n";
print "Target Commit/Branch:$target_commitish\n";
print "Release Title:       $release_title\n";
print "Changelog File:      " . ($changelog_file ne "" ? $changelog_file : "(none)") . "\n";
print "Draft:               " . ($is_draft ? "true" : "false") . "\n";
print "Prerelease:          " . ($is_prerelease ? "true" : "false") . "\n";
print "Auto Release Notes:  changelog file (GitHub commit generation disabled)\n";
print "Artifact:            $zip_path\n";
print "==============================\n";

if ($dry_run) {
    print "[Dry Run] Release simulation complete. No GitHub release created.\n";
    if ($release_body =~ /\S/) {
        print "\n[Dry Run] Release Notes Body Preview:\n";
        print "----------------------------------------\n";
        print $release_body;
        print "----------------------------------------\n";
    }
    exit 0;
}

my @headers = (
    '-H', 'Accept: application/vnd.github+json',
    '-H', "Authorization: Bearer $github_token",
    '-H', "X-GitHub-Api-Version: $github_api_version",
);
my $tag_url = "$api_url/tags/$tag_name";
my ($http_status, $response) = curl_response(@headers, $tag_url);
my $release_data;
if ($http_status == 404) {
    print "Creating GitHub Release...\n";
    my $request_file = json_file($payload);
    ($http_status, $response) = curl_response(@headers, '-X', 'POST',
        '-H', 'Content-Type: application/json', '--data-binary', "\@$request_file", $api_url);
    if ($http_status == 422 && $response =~ /already_exists/i) {
        ($http_status, $response) = curl_response(@headers, $tag_url);
    }
}
die "Error: Cannot create or retrieve GitHub release (HTTP $http_status).\nResponse: $response\n"
    unless $http_status >= 200 && $http_status < 300;
$release_data = $json_codec->decode($response);
die "Error: Invalid GitHub release response.\n"
    unless ref($release_data) eq 'HASH' && $release_data->{id};
my $release_id = $release_data->{id};
my $release_url = $release_data->{html_url} // '';

if (($release_data->{body} // '') ne $release_body ||
    ($release_data->{name} // '') ne $release_title ||
    !!$release_data->{draft} != !!$is_draft ||
    !!$release_data->{prerelease} != !!$is_prerelease) {
    my $request_file = json_file($payload);
    my ($status, $body) = curl_response(@headers, '-X', 'PATCH',
        '-H', 'Content-Type: application/json', '--data-binary', "\@$request_file", "$api_url/$release_id");
    die "Error: Cannot update release notes (HTTP $status).\nResponse: $body\n"
        unless $status == 200;
}

my $digest = 'sha256:' . file_digest($zip_path);
my $page = 1;
my @replace_assets;
while (1) {
    my ($status, $body) = curl_response(@headers, "$api_url/$release_id/assets?per_page=100&page=$page");
    die "Error: Cannot list release assets (HTTP $status).\nResponse: $body\n" unless $status == 200;
    my $assets = $json_codec->decode($body);
    die "Error: Invalid GitHub asset list.\n" unless ref($assets) eq 'ARRAY';
    for my $asset (@$assets) {
        next unless $asset->{name} eq $zip_name;
        if (($asset->{state} // '') eq 'uploaded' && ($asset->{digest} // '') eq $digest) {
            print "Release and matching asset already published: $release_url\n";
            exit 0;
        }
        die "Error: Asset '$zip_name' already exists but its digest differs or is unavailable. " .
            "Refusing to replace a published artifact without --rerelease.\n" unless $rerelease;
        die "Error: GitHub asset has no ID.\n" unless $asset->{id};
        push @replace_assets, $asset->{id};
    }
    last if @$assets < 100;
    $page++;
}

for my $asset_id (@replace_assets) {
    print "Replacing published asset '$zip_name' (ID: $asset_id) for explicit re-release...\n";
    my ($status, $body) = curl_response(@headers, '-X', 'DELETE', "$api_url/assets/$asset_id");
    die "Error: Cannot remove existing asset (HTTP $status).\nResponse: $body\n"
        unless $status == 204;
}

# ------------------------------------------------------------------------------
# Step 5: Upload Zip Asset
# ------------------------------------------------------------------------------
my $upload_url = "https://uploads.github.com/repos/$github_repo/releases/$release_id/assets?name=$zip_name";

print "Uploading asset $zip_name to GitHub release...\n";
my @upload_cmd = (
    "-X", "POST",
    "-H", "Accept: application/vnd.github+json",
    "-H", "Authorization: Bearer $github_token",
    "-H", "Content-Type: application/zip",
    "-H", "X-GitHub-Api-Version: $github_api_version",
    "--data-binary", "\@$zip_path",
    $upload_url
);

my ($upload_http_status, $upload_resp) = curl_response(@upload_cmd);

if ($upload_http_status >= 200 && $upload_http_status < 300) {
    my $asset = $json_codec->decode($upload_resp);
    die "Error: GitHub did not confirm the uploaded asset.\n"
        unless ref($asset) eq 'HASH' && $asset->{id} &&
            ($asset->{state} // '') eq 'uploaded' &&
            $asset->{name} eq $zip_name && $asset->{size} == -s $zip_path;
    print "Asset uploaded successfully (HTTP $upload_http_status)!\n";
    print "Release URL: $release_url\n";
} else {
    die "Error: Asset upload failed with HTTP status $upload_http_status.\nResponse: $upload_resp\n";
}
